def transform(grid):
    # Recolor the distinct 8-connected shapes in order, using colors 2,1,3,4.
    h, w = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            p=(y+dy,x+dx)
                            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==8 and p not in seen:
                                seen.add(p); stack.append(p)
                comps.append(comp)
    # Component order is top-to-bottom/left-to-right by topmost cell.
    comps.sort(key=lambda comp:min(comp))
    cols=[2,1,3,4]
    out=[row[:] for row in grid]
    for comp,col in zip(comps,cols):
        for r,c in comp: out[r][c]=col
    return out
